import datetime

GIGASECOND = 1_000_000_000

def add(moment):
    if isinstance(moment, datetime.datetime):
        base = moment
    elif isinstance(moment, datetime.date):
        # Convert date to datetime at midnight
        base = datetime.datetime(moment.year, moment.month, moment.day)
    else:
        raise TypeError("moment must be a datetime.date or datetime.datetime")
    return base + datetime.timedelta(seconds=GIGASECOND)
